function extractJson(value) {
  if (typeof value === 'object' && value !== null) {
    return value;
  }

  if (!value) {
    throw new Error("Réponse vide de l'agent recommandations");
  }

  let text = String(value)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  if (text.startsWith('"') && text.endsWith('"')) {
    try {
      text = JSON.parse(text);
    } catch (e) {}
  }

  text = String(text)
    .replace(/\\n/g, '\n')
    .replace(/\\"/g, '"')
    .trim();

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');

  if (start === -1 || end === -1 || end <= start) {
    throw new Error("Aucun objet JSON trouvé dans la réponse : " + text.slice(0, 500));
  }

  return JSON.parse(text.slice(start, end + 1));
}

const raw = $json.output ?? $json.text ?? $json.response ?? $json;

let recommandations = extractJson(raw);

if (recommandations.suggestion_recommandations) {
  recommandations = recommandations.suggestion_recommandations;
}

return [
  {
    json: {
      suggestion_recommandations: recommandations
    }
  }
];

const suggestionRecommandations = $('parser recommandations').item.json.suggestion_recommandations;
const verification = $('vérification recommandations code').item.json;

return [
  {
    json: {
      success: true,
      statut: "recommandations_valides",
      message: "Recommandations générées avec succès",
      suggestion_recommandations: suggestionRecommandations,
      verification
    }
  }
];

const verification = $('vérification recommandations code').item.json;

return [
  {
    json: {
      success: false,
      statut: "a_regenerer",
      message: "Les recommandations doivent être régénérées",
      verification,
      erreurs: verification.erreurs || []
    }
  }
];

const input = $json.body ?? $json;

return [
  {
    json: {
      entreprise_id: input.entreprise_id ?? input.entreprise?.id ?? null,
      resultat_id: input.resultat_id ?? input.resultat_carbone_id ?? null,
      resultat_carbone_id: input.resultat_carbone_id ?? input.resultat_id ?? null,
      entreprise: input.entreprise ?? {},
      resultat_carbone: input.resultat_carbone ?? input.resultats ?? {},
      facteurs_eleves: input.facteurs_eleves ?? [],
      details_resultat: input.details_resultat ?? input.resultats?.details ?? [],
      seuils_carbone: input.seuils_carbone ?? {}
    }
  }
];

const initial = $('Préparer les données recommandations').item.json ?? {};
const data = $('parser recommandations').item.json.suggestion_recommandations ?? {};

const erreurs = [];

if (data.statut !== 'genere') {
  erreurs.push("Le statut des recommandations doit être genere.");
}

if (!data.suggestion || typeof data.suggestion !== 'object') {
  erreurs.push("La réponse ne contient pas d’objet suggestion.");
}

if (!Array.isArray(data.recommandations)) {
  erreurs.push("La réponse ne contient pas un tableau recommandations.");
}

const recommandations = Array.isArray(data.recommandations) ? data.recommandations : [];
const facteursEleves = initial.facteurs_eleves ?? [];

const categoriesAutorisees = new Set(
  facteursEleves.map(f => f.categorie).filter(Boolean)
);

const facteursAutorises = new Set(
  facteursEleves.map(f => f.facteur_nom).filter(Boolean)
);

const priorites = ['faible', 'moyenne', 'elevee'];

for (const [index, reco] of recommandations.entries()) {
  if (!reco.source_emission) {
    erreurs.push(`Recommandation ${index + 1} : source_emission manquante.`);
  }

  if (!reco.probleme_detecte) {
    erreurs.push(`Recommandation ${index + 1} : probleme_detecte manquant.`);
  }

  if (!reco.action_proposee) {
    erreurs.push(`Recommandation ${index + 1} : action_proposee manquante.`);
  }

  if (!reco.priorite) {
    erreurs.push(`Recommandation ${index + 1} : priorite manquante.`);
  }

  if (reco.priorite && !priorites.includes(reco.priorite)) {
    erreurs.push(`Recommandation ${index + 1} : priorité invalide ${reco.priorite}.`);
  }

  if (!reco.impact_carbone) {
    erreurs.push(`Recommandation ${index + 1} : impact_carbone manquant.`);
  }

  if (reco.categorie && categoriesAutorisees.size > 0 && !categoriesAutorisees.has(reco.categorie)) {
    erreurs.push(`Recommandation ${index + 1} : catégorie non présente dans les facteurs élevés : ${reco.categorie}.`);
  }

  if (reco.facteur_nom && facteursAutorises.size > 0 && !facteursAutorises.has(reco.facteur_nom)) {
    erreurs.push(`Recommandation ${index + 1} : facteur non présent dans les facteurs élevés : ${reco.facteur_nom}.`);
  }
}

const texte = JSON.stringify(data).toLowerCase();

if (texte.includes('tva')) {
  erreurs.push("Les recommandations ne doivent pas contenir de TVA carbone.");
}

if (texte.includes('tnd')) {
  erreurs.push("Les recommandations ne doivent pas contenir de TND.");
}

return [
  {
    json: {
      valide: erreurs.length === 0,
      statut: erreurs.length === 0 ? "valide" : "a_regenerer",
      erreurs,
      message: erreurs.length === 0 ? "Recommandations valides" : "Les recommandations doivent être régénérées"
    }
  }
];
